import{_ as o,o as u,c as q,ag as r}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"02 房产实战与多空论战（13篇精读笔记）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/notes/02_房产实战与多空论战.md","filePath":"topics/tianya/notes/02_房产实战与多空论战.md"}'),n={name:"topics/tianya/notes/02_房产实战与多空论战.md"};function s(a,t,g,e,i,l){return u(),q("div",null,[...t[0]||(t[0]=[r('<h1 id="_02-房产实战与多空论战-13篇精读笔记" tabindex="-1">02 房产实战与多空论战（13篇精读笔记） <a class="header-anchor" href="#_02-房产实战与多空论战-13篇精读笔记" aria-label="Permalink to &quot;02 房产实战与多空论战（13篇精读笔记）&quot;">​</a></h1><blockquote><p>覆盖13篇：38/40/41/42/44/46/48/50/69/80/88/100/197，作者与年代见各节；观点均摘自原文。</p></blockquote><h2 id="_38-朴实的预言1——房价10年内都不会跌-经济分析终结者-2010-6起" tabindex="-1">38 朴实的预言1——房价10年内都不会跌（经济分析终结者，2010.6起） <a class="header-anchor" href="#_38-朴实的预言1——房价10年内都不会跌-经济分析终结者-2010-6起" aria-label="Permalink to &quot;38 朴实的预言1——房价10年内都不会跌（经济分析终结者，2010.6起）&quot;">​</a></h2><p><strong>核心论点</strong>：①房价不高：1990/2000/2010年人均年收入都只够买2-3平米，购买力比从未恶化，品质还在升级；②城市化+改善需求两大买家支撑；③成本刚性：建安2000+土地拆迁1500+税费利润1000；④港日泡沫破裂后房价仍高位，&quot;中国说泡沫太可笑&quot;；⑤土地财政无法摆脱，地方债务比房价更急，调控只会&quot;抑制快速上涨&quot;，且通胀下房产是唯一避险品。 <strong>方法论</strong>：用&quot;购买力比、成本、供需、财政依赖&quot;四把尺子简化问题；用平均数口径而非个例反驳对手。 <strong>金句</strong>：&quot;房价是市民用钞票投票的结果&quot;；&quot;老百姓谁没有房子住？请看看你身边的人！&quot; <strong>预测对照</strong>：&quot;10年内不跌&quot;在2010-2020尺度大体应验，他反复回帖炫耀&quot;应验&quot;；但2021年见顶后一二线普遍阴跌两三成，恰好卡在最后两年。<strong>部分准</strong>：长期方向对，边界错，&quot;房价不高&quot;被后来的居民杠杆见顶证伪。</p><h2 id="_40-最后的救市——换入大城市房子的最后时刻-鹏程蛇口-2015-5-2017-1" tabindex="-1">40 最后的救市——换入大城市房子的最后时刻（鹏程蛇口，2015.5-2017.1） <a class="header-anchor" href="#_40-最后的救市——换入大城市房子的最后时刻-鹏程蛇口-2015-5-2017-1" aria-label="Permalink to &quot;40 最后的救市——换入大城市房子的最后时刻（鹏程蛇口，2015.5-2017.1）&quot;">​</a></h2><p><strong>核心论点</strong>：①930/330新政是&quot;最后一次大规模救市&quot;，救的是地方财政与债务而非房地产；②房价冰火两重天：一线强二线屡创新高，三四线&quot;没有最低只有更低&quot;；③最值得投资的11城：北上广深+厦津宁杭渝汉蓉；④城市化进入第二阶段（小城→大城），人口流入决定一切；⑤&quot;未来优质资产收入远高于工资收入&quot;，买对房与没买对房就是富人和穷人之别。 <strong>方法论</strong>：政策窗口（救市=最后的低价机会）+人口流向+高端就业岗位三因子选城，卖三四线、换一线强二线。 <strong>金句</strong>：&quot;这次救市是最后一次出手机会，否则面对的是有价无市、砸在手里&quot;；&quot;用不了十年，同样学历职业的人，就因房子分成富人和穷人。&quot; <strong>预测对照</strong>：2015-2017一线暴涨，短期全中；但他借帖引流建18个微信房产群卖课，立场需打折。2026年回看，一线2021年也见顶回落，&quot;屡创新高&quot;停在2021；三四线未&quot;永远阴跌&quot;（棚改又涨一轮）。<strong>部分准</strong>。</p><h2 id="_41-老公坚持房价会跌-我现在一看房价就满嘴吐血-爱死小肥羊-2010-1-2015-1" tabindex="-1">41 老公坚持房价会跌，我现在一看房价就满嘴吐血（爱死小肥羊，2010.1-2015.1） <a class="header-anchor" href="#_41-老公坚持房价会跌-我现在一看房价就满嘴吐血-爱死小肥羊-2010-1-2015-1" aria-label="Permalink to &quot;41 老公坚持房价会跌，我现在一看房价就满嘴吐血（爱死小肥羊，2010.1-2015.1）&quot;">​</a></h2><p><strong>核心论点</strong>（纪实帖）：①男友笃信牛刀，徐州三环4000元/平坚持&quot;不到3500不出手&quot;，坚信2010年初必跌；②空军心态=只接受对自己有利的信息，&quot;就像国家跟他商量过似的&quot;；③看房四年，房价3000+涨到7500，两人由吵到分手，女方考进银行重启人生；④2015年楼主已为人母，自嘲&quot;失去的都是珍宝&quot;。 <strong>方法论</strong>：无框架，价值在于&quot;傻空心理标本&quot;：预测失败的成本不是钱，是青春与婚约；跟帖中&quot;设观察期，到期就买&quot;的自住决策法最实用。<strong>金句</strong>：&quot;房价涨跌不过区区几万，这时间这青春年华才是最宝贵的！&quot; <strong>预测对照</strong>：空方2010-2011在徐州被打脸；但拉长到2026年，徐州这类城市正是&quot;阴跌十年&quot;的重灾区——短期大错，长期歪打正着。</p><h2 id="_42-今年-我什么都不再预测-exposurejingdong-2016-7首贴-2017-11-2018-8重发" tabindex="-1">42 今年，我什么都不再预测（exposureJINGDONG，2016.7首贴，2017.11-2018.8重发） <a class="header-anchor" href="#_42-今年-我什么都不再预测-exposurejingdong-2016-7首贴-2017-11-2018-8重发" aria-label="Permalink to &quot;42 今年，我什么都不再预测（exposureJINGDONG，2016.7首贴，2017.11-2018.8重发）&quot;">​</a></h2><p><strong>核心论点</strong>：①2016年7月断言&quot;40年来首次衰退&quot;，&quot;不是保6问题，是负数问题&quot;；②川普必当选且必打贸易战，&quot;他要抢的是中国的工作&quot;；③人民币必贬、外汇管制必收紧，自称劝某航高层换美元避掉60多亿美元汇兑损失；④北京房价2017年量价齐跌；⑤&quot;99.9%的人看完也没用，你该怎么完还是怎么完&quot;。 <strong>方法论</strong>：宏观地缘+货币周期自上而下推演；但满篇&quot;准确率100%&quot;的自我加冕，可证伪性差，属立场先行的悲观预言家。 <strong>金句</strong>：&quot;中国不可能当什么老大&quot;；&quot;事实将好好教育99.9%&quot;。 <strong>预测对照</strong>：川普当选、贸易战、外汇收紧、北京2017量跌——<strong>大体准</strong>，在2026年语境下最有先见；但&quot;大幅全跌&quot;&quot;一年白干&quot;的崩盘节奏2017-2018未兑现，全面下跌要等到2021后。结论可参考，口吻不可效仿。</p><h2 id="_44-北京十年房子故事-看西山的子房-2013-8-2018-12" tabindex="-1">44 北京十年房子故事（看西山的子房，2013.8-2018.12） <a class="header-anchor" href="#_44-北京十年房子故事-看西山的子房-2013-8-2018-12" aria-label="Permalink to &quot;44 北京十年房子故事（看西山的子房，2013.8-2018.12）&quot;">​</a></h2><p><strong>核心论点</strong>：①2003年揣几千元、靠父母+同学借款上车北五环外2300元/平的房，十年升值十几倍；②买房先判断大趋势，其次才是&quot;该不该用父母的钱&quot;；③用Excel建模比较政策房与商品房20年动态成本（通胀按15-17%真实口径）；④&quot;货币可以预支，房子不能穿越&quot;——信贷扩张下实物资产必伴通胀，负债者食利存款者；⑤经济活动只分创造财富与分配财富；⑥2018年判断中美进入长期敌对、行业严冬。 <strong>方法论</strong>：超长周期观——&quot;不知道这轮周期处在少年还是中年&quot;，反对在孩子8岁时喊&quot;你早晚得死&quot;；只投&quot;有核心竞争力的优等生城市&quot;（京沪杭）。 <strong>金句</strong>：&quot;生长期的孩子也会生长痛，但不妨碍他生长&quot;；&quot;通胀下，负债者在食利于存款者&quot;。 <strong>预测对照</strong>：2013-2018看多北京被验证；2018年警示中美对抗、行业严冬，2026年回看极准。<strong>基本准</strong>，是本批中框架最完整、心态最稳的多方。</p><h2 id="_46-现在房产投资绝对是个技术活-海男的故事-2016-5-2018-12" tabindex="-1">46 现在房产投资绝对是个技术活（海男的故事，2016.5-2018.12） <a class="header-anchor" href="#_46-现在房产投资绝对是个技术活-海男的故事-2016-5-2018-12" aria-label="Permalink to &quot;46 现在房产投资绝对是个技术活（海男的故事，2016.5-2018.12）&quot;">​</a></h2><p><strong>核心论点</strong>：①遍地黄金时代结束，只有约10个城市有投资价值，北上深最优；②短期房价由首付、利率、政策决定，长期由人口决定，人口净流出城市绝对不碰；③11年限购挖了第一个坑（资金被迫去三四线），当下正挖第二个坑（都市圈不限购小城市）——&quot;租不掉、卖不掉、住不了&quot;；④限购限贷是房产投资的福音：人为制造供不应求，造就&quot;逼空式上涨&quot;；⑤房价公式：地段30-40%+小区品质20-30%+学区商业；⑥2018年判断泡沫不破，因非自住房源不会集中抛售；&quot;什么时候大跌？经济危机&quot;。 <strong>方法论</strong>：二手房流动性测试（能否顺利卖掉）、CBD通勤时间定地段、面积-人群匹配换仓、政策挖坑反着走。 <strong>金句</strong>：&quot;错误的投资会使人走向绝境，切记切记切记&quot;；&quot;限购限贷是房产投资的福音！（重要的话说三遍）&quot;。 <strong>预测对照</strong>：环京与都市圈小城市暴跌被精准预警；&quot;泡沫不破，除非经济危机&quot;——2021-2026正是&quot;经济下行+温和下跌&quot;组合，<strong>大部分准</strong>，是13篇中可操作性最强的一篇。</p><h2 id="_48-中国的房价将在不断上涨中完成腰斩-小恶魔兰尼特斯-2016-2-12" tabindex="-1">48 中国的房价将在不断上涨中完成腰斩（小恶魔兰尼特斯，2016.2-12） <a class="header-anchor" href="#_48-中国的房价将在不断上涨中完成腰斩-小恶魔兰尼特斯-2016-2-12" aria-label="Permalink to &quot;48 中国的房价将在不断上涨中完成腰斩（小恶魔兰尼特斯，2016.2-12）&quot;">​</a></h2><p><strong>核心论点</strong>：①房价还会涨（3万→15万），但牛肉面20→200元、黄金250→5000元/克，涨幅跑输必需品与黄金，购买力口径完成&quot;无痛人流式腰斩&quot;；②若货币出幺蛾子则以新币计价；③&quot;如果房价下跌，平民更买不起房&quot;；④资本金字塔：县城→省会→北上广→洛杉矶，弱者逐层被挤出，&quot;工作在苏州住无锡&quot;是开发商诱骗小资本接盘；⑤怀疑宏观数据造假（1985年苏联翻版）。 <strong>方法论</strong>：购买力/黄金本位的相对价值分析，把名义上涨与实际贬值拆开。 <strong>金句</strong>：&quot;房价开始跌了吗？——已经结束了&quot;；&quot;黄金是一面照妖镜&quot;。 <strong>预测对照</strong>：名义房价没到15万，但2021-2026房价下跌叠加物价上涨，&quot;上涨中阴跌&quot;的相对贬值叙事部分应验；黄金2026年远超250元/克，距5000元尚远。<strong>部分准</strong>：方向对、幅度夸张。</p><h2 id="_50-看一个穷人怎样拥有多套房产-晋朝人-2009-5-2018-2" tabindex="-1">50 看一个穷人怎样拥有多套房产（晋朝人，2009.5-2018.2） <a class="header-anchor" href="#_50-看一个穷人怎样拥有多套房产-晋朝人-2009-5-2018-2" aria-label="Permalink to &quot;50 看一个穷人怎样拥有多套房产（晋朝人，2009.5-2018.2）&quot;">​</a></h2><p><strong>核心论点</strong>（武汉工薪族自述）：①1999年靠房贷上车，从1套滚到多套，靠的是&quot;穷人怕借钱，富人喜融资&quot;；②只要租金能覆盖月供，&quot;借的越多赚的越多&quot;，杠杆+复利是普通人唯一可用的引擎；③观念决定贫富：穷人眼里的世界钱太少，富人眼里遍地黄金；④对成功者要&quot;放下自我，观察、学习、跟随&quot;；⑤商铺风险远大于住宅，只有&quot;成熟专业市场中的商铺&quot;值得碰。 <strong>方法论</strong>：低成本高杠杆+现金流覆盖月供的&quot;买入即赚钱&quot;模型；多写失败教训少写成功。 <strong>金句</strong>：&quot;富人借钱叫融资，穷人借钱叫背债&quot;；&quot;看着两人都买房，有人赚有人赔，那是因为两人在做不同的事情&quot;。 <strong>预测对照</strong>：其2009年&quot;武汉必补涨沿海&quot;的判断在2010-2016兑现；商铺观点被电商冲击完全应验；但&quot;杠杆至上&quot;框架在2021年后的阴跌中开始反噬。<strong>早期准，后期需修正</strong>。</p><h2 id="_69-理性探讨楼市趋势-熊鞍-2017-5-2018-8" tabindex="-1">69 理性探讨楼市趋势（熊鞍，2017.5-2018.8） <a class="header-anchor" href="#_69-理性探讨楼市趋势-熊鞍-2017-5-2018-8" aria-label="Permalink to &quot;69 理性探讨楼市趋势（熊鞍，2017.5-2018.8）&quot;">​</a></h2><p><strong>核心论点</strong>（剪报型长贴）：①商办新政3天签约跌99.9%，限购令交易链上所有人被冻住；②2017房贷利率四连升、新增房贷将被砍半，资金面趋紧；③去杠杆=货币收缩=资产价格下行：&quot;去年在暴涨中没买到房的朋友，你们是幸运的&quot;；④2018年7月政治局&quot;坚决遏制房价上涨&quot;+房地产税提速+深圳首个限售。 <strong>方法论</strong>：以政策文本与资金面数据（国债收益率、房贷利率、居民杠杆率）做日更追踪，把调控当主要自变量。 <strong>金句</strong>：&quot;去杠杆，就是让负债变少；钱变少之后，资产价格自然下来&quot;；&quot;经济周期一直都在，只是大众总是迟钝的。&quot; <strong>预测对照</strong>：2017-2018判断&quot;资金面决定拐点&quot;，当年成交量即腰斩；但全国性房价下跌迟至2021年后，&quot;没买房的是幸运的&quot;当年错、2026年对——<strong>方向对，时间差错三年</strong>。</p><h2 id="_80-房奴十年-房奴十年-2010-5-2018-11日更" tabindex="-1">80 房奴十年（房奴十年，2010.5-2018.11日更） <a class="header-anchor" href="#_80-房奴十年-房奴十年-2010-5-2018-11日更" aria-label="Permalink to &quot;80 房奴十年（房奴十年，2010.5-2018.11日更）&quot;">​</a></h2><p><strong>核心论点</strong>（生活实录）：①深圳打工女2010年高位购50万偏远期房，月入7000、月供2784，立帖&quot;直至房贷结束&quot;；②为还贷住十元店、日餐3元、打多份兼职，把房奴生活&quot;诗意化&quot;；③记录租房时代被房东九次驱赶的屈辱——&quot;有房&quot;是尊严问题；④2018年仍在记账：月租550租住市区，自有房出租。 <strong>方法论</strong>：无预测，用十年流水账量化&quot;普通人在大城市拥有住房的真实成本&quot;。 <strong>金句</strong>：&quot;每一个房子的背后都是一个辛酸的故事&quot;；&quot;买了房子，就是给心安顿一个家&quot;。 <strong>预测对照</strong>：不涉及预测。2010年买在偏远片区，2026年大概率横盘阴跌，&quot;月供即枷锁&quot;是后来&quot;房价未崩、钱包先崩&quot;时代的预演。</p><h2 id="_88-限购下卖房买房-我被中介撞了一下腰-dindindanglaile-2017-6-2019-2" tabindex="-1">88 限购下卖房买房，我被中介撞了一下腰（dindindanglaile，2017.6-2019.2） <a class="header-anchor" href="#_88-限购下卖房买房-我被中介撞了一下腰-dindindanglaile-2017-6-2019-2" aria-label="Permalink to &quot;88 限购下卖房买房，我被中介撞了一下腰（dindindanglaile，2017.6-2019.2）&quot;">​</a></h2><p><strong>核心论点</strong>（深圳龙岗实操）：①限购下&quot;先卖后买&quot;的换房链条极脆弱，政策、买家贷款、中介话术环环翻车；②中介的&quot;谈判专家&quot;实为帮卖家抬价，佣金3个点决定其立场；③融资买二套需房价年涨15%才不亏，&quot;有多大能力办多大事&quot;；④2018-2019日更见证龙岗二手跌回2015年、法拍房流拍、商铺空置、亲友&quot;因房返贫&quot;；⑤结论：卖掉后不买，持币租房，&quot;现在才是开始&quot;。 <strong>方法论</strong>：一线亲历+链家/中原价格截图数据库+身边消费降级观察（商场、汽配街）交叉验证拐点。 <strong>金句</strong>：&quot;刚需啥时候上车都对？一年时间不到，小100万没了，嘴炮们能给你？&quot;；&quot;顶点6124、底部1664，你为什么盼着在4000点抄底？&quot; <strong>预测对照</strong>：2018年看空深圳外围、2019年初判断&quot;放开限购是决堤前最后的泄洪&quot;——临深与龙岗正是后来跌幅最深的区域，<strong>准</strong>；代价是2019-2021反弹踏空，帖中未复盘。</p><h2 id="_100-房地产投资依然无忧-逆向思维让你找到真实-66端午88-2011-1-2019-3-核心论点-1地方政府税收约八成由房地产产业链提供-含土地出让-伤税收的政策都会打折执行-2中国经济建立在国家意志之上-崩溃论-绝无可能-2011-2012是-钝刀割肉-3房产仍是最佳防御资产-但要看成本、现金流、稀缺性-策略-等小幅回调逢低买入、持有者拉高租金-4商铺金融属性过重-电商冲击下应逢高卖出-其2003年2-8万-平商铺对照2000元住宅的教训-52019年结论-没有任何一种大类资产可以长期跑赢货币增长-房地产也没有-——18年房价涨10倍-3倍杠杆放大成30倍财富。" tabindex="-1">100 房地产投资依然无忧，逆向思维让你找到真实（66端午88，2011.1-2019.3）<strong>核心论点</strong>：①地方政府税收约八成由房地产产业链提供（含土地出让），伤税收的政策都会打折执行；②中国经济建立在国家意志之上，&quot;崩溃论&quot;绝无可能，2011-2012是&quot;钝刀割肉&quot;；③房产仍是最佳防御资产，但要看成本、现金流、稀缺性；策略：等小幅回调逢低买入、持有者拉高租金；④商铺金融属性过重，电商冲击下应逢高卖出（其2003年2.8万/平商铺对照2000元住宅的教训）；⑤2019年结论：&quot;没有任何一种大类资产可以长期跑赢货币增长，房地产也没有&quot;——18年房价涨10倍，3倍杠杆放大成30倍财富。 <a class="header-anchor" href="#_100-房地产投资依然无忧-逆向思维让你找到真实-66端午88-2011-1-2019-3-核心论点-1地方政府税收约八成由房地产产业链提供-含土地出让-伤税收的政策都会打折执行-2中国经济建立在国家意志之上-崩溃论-绝无可能-2011-2012是-钝刀割肉-3房产仍是最佳防御资产-但要看成本、现金流、稀缺性-策略-等小幅回调逢低买入、持有者拉高租金-4商铺金融属性过重-电商冲击下应逢高卖出-其2003年2-8万-平商铺对照2000元住宅的教训-52019年结论-没有任何一种大类资产可以长期跑赢货币增长-房地产也没有-——18年房价涨10倍-3倍杠杆放大成30倍财富。" aria-label="Permalink to &quot;100 房地产投资依然无忧，逆向思维让你找到真实（66端午88，2011.1-2019.3）**核心论点**：①地方政府税收约八成由房地产产业链提供（含土地出让），伤税收的政策都会打折执行；②中国经济建立在国家意志之上，&quot;崩溃论&quot;绝无可能，2011-2012是&quot;钝刀割肉&quot;；③房产仍是最佳防御资产，但要看成本、现金流、稀缺性；策略：等小幅回调逢低买入、持有者拉高租金；④商铺金融属性过重，电商冲击下应逢高卖出（其2003年2.8万/平商铺对照2000元住宅的教训）；⑤2019年结论：&quot;没有任何一种大类资产可以长期跑赢货币增长，房地产也没有&quot;——18年房价涨10倍，3倍杠杆放大成30倍财富。&quot;">​</a></h2><p><strong>方法论</strong>：财政依赖度测算+国家/民营二元资金博弈+逆向思维（预判政策打折）。 <strong>金句</strong>：&quot;趋势不会轻易转向，尤其已延续10年，你怎么断定未来10年不延续？&quot;；&quot;钝刀割肉，绝不是崩溃。&quot; <strong>预测对照</strong>：2011年成功预判调控打折、2012年反弹；2017年&quot;整体稍高估、由一线贡献&quot;到2021年前都对；但&quot;逢低买入永远无忧&quot;的信仰在2021后被击穿。<strong>前十年准，终局判断被证伪</strong>。</p><h2 id="_197-论房产的获得与坚守-不炒不热闹-2020-2-3" tabindex="-1">197 论房产的获得与坚守（不炒不热闹，2020.2-3） <a class="header-anchor" href="#_197-论房产的获得与坚守-不炒不热闹-2020-2-3" aria-label="Permalink to &quot;197 论房产的获得与坚守（不炒不热闹，2020.2-3）&quot;">​</a></h2><p><strong>核心论点</strong>：①房产是家庭的存钱罐：一代人存一辈子才有一套，指望子女继承多套不现实（卖房炒股、创业、赌博不断打破存钱罐）；②北京年二手换手率约2%，&quot;获得房产很难，守住30年更难&quot;；③父母房产最正确的用途是自养老，而非留给子女；④房价就是物价，售租比600-1000倍在低利率+高增长+爱买房的国情下长期成立；⑤买房像种地：&quot;春天该播种就播种，不要为恶劣气候担心。&quot; <strong>方法论</strong>：用换手率、人均GDP城市榜、售租比国际比较等朴素数据反驳&quot;下一代房子过剩论&quot;。 <strong>金句</strong>：&quot;守住一套房产更难，因为你要忍住30年之内无数次花钱的冲动&quot;；&quot;聪明的人从别人的经验教训中学习，愚蠢的人屡战屡败永远不会成长。&quot; <strong>预测对照</strong>：发帖于2020年3月疫情低点，&quot;该播种就播种&quot;随后迎来最后的大涨——局部准；2026年回看，售租比&quot;常态论&quot;正被租金下行、人口负增长挑战。<strong>上半场准，下半场存疑</strong>。</p><h2 id="总览与心得" tabindex="-1">总览与心得 <a class="header-anchor" href="#总览与心得" aria-label="Permalink to &quot;总览与心得&quot;">​</a></h2><p><strong>多空谁笑到了最后</strong>：2010-2021年多方完胜——38、40、44、46、50、100、197的判断先后兑现，空军（41的牛刀信徒）付出真金白银与婚约的代价；42、69、88等空方虽长期正确，却在正确的年代被视为疯子，且常错过反弹。转折在2021年：此后多方只剩一线核心的&quot;防御性正确&quot;。2026年回看，全程成立的是<strong>带条件的判断</strong>（46的&quot;除非经济危机&quot;、100的&quot;不跑赢货币&quot;、44的&quot;超长周期&quot;），全程错误的是<strong>无条件的信仰</strong>（&quot;10年不跌&quot;&quot;永远屡创新高&quot;）。 <strong>普通人能带走的教训</strong>：①预测房价不如预测自己——自住看承受力与现金流（41、80），投资看人口、资金面与流动性（46、69）；②&quot;借得起的杠杆+租得掉的房&quot;是普通人放大财富的合法引擎，但杠杆只在上涨周期是朋友（50）；③政策是最大变量：限购是多方福音，去杠杆是空方号角，读懂财政依赖度才能预判政策打折（100、38）；④换手率与二手房流动性是最诚实的体温计，媒体和中介的嗓门不是（88、46）；⑤空仓与满仓的代价同样真实，最稳姿势是&quot;优质城市核心资产+足够现金流+不赌单边&quot;（44、197）；⑥警惕一切&quot;准确率100%&quot;的作者：口吻越全知，越接近流量生意（40、42）。</p>',30)])])}const _=o(n,[["render",s]]);export{d as __pageData,_ as default};
